50	function usePersistentState<T>(key: string, fallback: T) {
51	  const [value, setValue] = useState<T>(() => {
52	    try {
53	      const saved = localStorage.getItem(key);
54	      return saved ? JSON.parse(saved) as T : fallback;
55	    } catch {
56	      return fallback;
57	    }
58	  });
59	  useEffect(() => {
60	    localStorage.setItem(key, JSON.stringify(value));
61	  }, [key, value]);
62	  return [value, setValue] as const;
63	}
